/**
 * Feature mount points. The shell renders exactly one workspace feature at a
 * time inside a full-size container; each feature reads the plan store itself.
 *
 * To work on a feature, edit only its own directory. Do not edit this file or
 * the shell: ask the contract owner if a mount point is missing.
 */
import { Box, Footprints, PencilRuler, type LucideIcon } from 'lucide-react';
import { lazy, type ComponentType, type LazyExoticComponent } from 'react';

export type WorkspaceMode = 'plan' | 'design' | 'walk';

export interface WorkspaceFeature {
  mode: WorkspaceMode;
  label: string;
  hint: string;
  icon: LucideIcon;
  component: LazyExoticComponent<ComponentType>;
}

export const WORKSPACE_FEATURES: WorkspaceFeature[] = [
  { mode: 'plan', label: 'Plan', hint: 'Edit walls, doors, windows and rooms', icon: PencilRuler, component: lazy(() => import('./editor2d')) },
  { mode: 'design', label: 'Design', hint: 'Furnish and style in 3D', icon: Box, component: lazy(() => import('./viewer3d')) },
  { mode: 'walk', label: 'Walk', hint: 'Walk through your home', icon: Footprints, component: lazy(() => import('./walkthrough')) },
];

/** Full-page flow at /import: upload a PDF, review, create the project. */
export const ImportFeature = lazy(() => import('./import'));
